// Original guided activities. Textbook examples remain attributed on materials.html.
(()=>{
const units={
oi:{rule:'Для любого времени подходит Oi! Утром говорят Bom dia, после полудня Boa tarde, вечером Boa noite. На Tudo bem? можно ответить Tudo bem. Точка и вопросительный знак помогают различить ответ и вопрос.',words:[['Oi!','Привет!'],['Bom dia!','Доброе утро!'],['Boa tarde!','Добрый день!'],['Boa noite!','Добрый вечер! / Спокойной ночи!'],['Tudo bem?','Как дела?'],['Até amanhã!','До завтра!']],read:['Ana: Oi! Tudo bem?\nBia: Tudo bem! E você?\nAna: Tudo bem! Até amanhã!','Что делает Ана в конце?',['Прощается до завтра','Называет свой город','Заказывает кофе'],0],spell:['O_!','i','Oi! пишется двумя латинскими буквами: O и i.'],photo:['Esta é uma cidade.','Это город.','На фотографии видны город и горы. Cidade — город.'],model:['Oi! Tudo bem? Até amanhã!','Привет! Как дела? До завтра!'],write:'Напиши короткое приветствие и прощание. Можно пока повторить образец.'},
nome:{rule:'Шаблон имени: Eu + sou + имя. Другая готовая форма: Meu nome é + имя. Для начала выбери одну, а вторую научись узнавать.',words:[['eu','я'],['sou','форма «являюсь» для я'],['Meu nome é…','Меня зовут…'],['Como você se chama?','Как тебя зовут?']],read:['Ana: Oi! Eu sou Ana.\nPaulo: Meu nome é Paulo.\nAna: Prazer, Paulo!','Как зовут собеседника Аны?',['Paulo','Pedro','Ana'],0],spell:['n_me','o','Nome — имя. В середине буква o.'],photo:['As casas têm cores diferentes.','У домов разные цвета.','На фотографии Салвадора видны разноцветные дома. Casa — дом; cores — цвета.'],model:['Oi! Meu nome é Ana. Prazer!','Привет! Меня зовут Ана. Приятно познакомиться!'],write:'Представься соседу: приветствие, имя и короткая вежливая фраза.'},
origem:{rule:'Происхождение — откуда приехал: sou de Moscou. Место проживания — где живу: moro em Moscou. В этом уроке сначала тренируем только происхождение.',words:[['de onde','откуда'],['de Moscou','из Москвы'],['da Rússia','из России'],['do Brasil','из Бразилии']],read:['Meu nome é Ana. Sou da Rússia. Paulo é do Brasil.','Откуда Ана?',['Из России','Из Бразилии','Из Португалии'],0],spell:['R_ssia','ú','Rússia пишется с ú. В ответах ударение можно пропустить, но образец лучше запоминать с ним.'],photo:['O prédio tem muitas janelas.','У здания много окон.','Посмотри на фасад: prédio — здание, janelas — окна.'],model:['Oi! Meu nome é Ana. Sou da Rússia, de Moscou.','Привет! Меня зовут Ана. Я из России, из Москвы.'],write:'Напиши имя, страну и город происхождения. Используй готовые кусочки sou de / sou da.'},
estar:{rule:'С Eu запомни две отдельные формы: sou — кто я, estou — где я или как себя чувствую. Не пытайся заменить одну другой во всех ситуациях.',words:[['estou bem','мне хорошо'],['estou em casa','я дома'],['cansado / cansada','уставший / уставшая'],['agora','сейчас']],read:['Ana: Estou em casa. Estou cansada.\nPaulo: Eu estou bem.','Где Ана?',['Дома','В аптеке','На рынке'],0],spell:['est_u','o','Estou — форма estar для eu.'],photo:['Há um prédio e nuvens.','Есть здание и облака.','Сначала назови то, что видишь: prédio — здание; nuvens — облака.'],model:['Estou em casa. Estou bem. E você?','Я дома. У меня всё хорошо. А у тебя?'],write:'Напиши, где ты сейчас и как себя чувствуешь. Достаточно двух коротких фраз.'},
artigos:{rule:'Для определённого предмета: o livro, a casa. Для пока неизвестного: um livro, uma casa. Меняется маленькое слово, а не само название предмета.',words:[['o livro','книга'],['a casa','дом'],['um livro','какая-то книга'],['uma casa','какой-то дом']],read:['Esta é uma casa. A casa é bonita. Há um livro na casa.','Какое слово сочетается с casa?',['a / uma','o / um','eu / sou'],0],spell:['c_sa','a','Casa — дом. Запоминай вместе с a.'],photo:['Há árvores na paisagem.','В пейзаже есть деревья.','Árvores — деревья. Эта форма означает несколько деревьев.'],model:['Esta é uma casa. A casa é bonita.','Это дом. Дом красивый.'],write:'Опиши два предмета с артиклями. Можно использовать casa и livro.'},
nao:{rule:'Утверждение: Eu falo. Отрицание: Eu não falo. Вопрос: Você fala? Сначала меняй только один кусочек фразы, чтобы увидеть разницу.',words:[['não','не / нет'],['falo','говорю'],['um pouco','немного'],['português','португальский язык']],read:['Ana: Você fala português?\nBia: Eu falo um pouco.\nAna: Eu não falo muito.','Как Биа оценивает свой португальский?',['Говорит немного','Совсем не говорит','Говорит только по телефону'],0],spell:['n_o','ã','Não пишется с ã: носовое звучание лучше повторять за записью.'],photo:['Há uma igreja e árvores.','Есть церковь и деревья.','Igreja — церковь; árvores — деревья.'],model:['Eu falo um pouco de português. Não entendi. Pode repetir?','Я немного говорю по-португальски. Не понял. Можете повторить?'],write:'Сообщи, что пока говоришь немного. Если нужно, попроси повторить.'},
ter:{rule:'В русском «у меня есть», в португальском Eu tenho. С você форма другая: você tem. Возраст — Tenho vinte anos, а не «я есть двадцать».',words:[['tenho','у меня есть'],['tem','у тебя / него / неё есть'],['anos','годы; используется для возраста'],['uma irmã','сестра']],read:['Ana tem uma irmã. A irmã tem vinte anos. Paulo tem um irmão.','Кто есть у Аны?',['Сестра','Два брата','Сын'],0],spell:['t_nho','e','Tenho — у меня есть.'],photo:['Há prédios na cidade.','В городе есть здания.','Prédios — здания. Не нужно придумывать, кто в них живёт.'],model:['Tenho uma irmã. Ela tem vinte anos.','У меня есть сестра. Ей двадцать лет.'],write:'Напиши две фразы о семье или возрасте. Можно описать вымышленного человека.'},
familia:{rule:'Выбор meu/minha зависит от следующего слова: meu irmão, minha irmã. Если предметов несколько: meus livros, minhas casas. Сначала отработай единственное число.',words:[['meu irmão','мой брат'],['minha irmã','моя сестра'],['minha família','моя семья'],['nossa casa','наш дом']],read:['Esta é minha família. Meu irmão é Paulo. Minha irmã é Ana.','Кто такой Паулу?',['Брат','Сестра','Сосед'],0],spell:['min_a','h','Minha — моя. Nh передаёт мягкий носовой звук; слушай готовое слово.'],photo:['Há prédios e água na paisagem.','В пейзаже есть здания и вода.','Prédios — здания; paisagem — пейзаж.'],model:['Esta é minha família. Meu irmão é Paulo. Minha irmã é Ana.','Это моя семья. Моего брата зовут Паулу. Мою сестру зовут Ана.'],write:'Подпиши фотографию семьи тремя короткими фразами. Имена могут быть вымышленными.'},
rotina:{rule:'Начальная форма на -ar: estudar. Для eu убираем -ar и ставим -o: estudo. Для você ставим -a: estuda. Это рабочая схема для многих обычных действий, но не для всех глаголов.',words:[['moro','живу'],['trabalho','работаю'],['estudo','учусь / изучаю'],['todos os dias','каждый день']],read:['Ana mora no Brasil. Ela trabalha de manhã e estuda português à noite.','Когда Ана изучает португальский?',['Вечером','Утром','Только в воскресенье'],0],spell:['est_do','u','Eu estudo — я учусь.'],photo:['Esta é uma estufa.','Это оранжерея.','На снимке оранжерея в Куритибе. Estufa — оранжерея.'],model:['Moro no Brasil. Trabalho de manhã. Estudo português à noite.','Я живу в Бразилии. Работаю утром. Учу португальский вечером.'],write:'Расскажи в трёх фразах, где живёшь, чем занимаешься и когда учишься.'},
gostar:{rule:'Схема: кто + форма gostar + de + то, что нравится. Eu gosto de música. Если дальше действие, оставляем начальную форму: gosto de estudar.',words:[['gosto de','мне нравится'],['música','музыка'],['café','кофе'],['estudar','учиться']],read:['Ana gosta de música. Paulo gosta de café. Os dois gostam de estudar português.','Что нравится им обоим?',['Учить португальский','Только кофе','Только музыка'],0],spell:['g_sto','o','Eu gosto de… — мне нравится…'],photo:['Há água e um pôr do sol.','Есть вода и закат.','Pôr do sol — закат. Для мнения: Eu gosto desta paisagem — мне нравится этот пейзаж.'],model:['Gosto de música e de café. Também gosto de estudar português.','Мне нравятся музыка и кофе. Ещё мне нравится учить португальский.'],write:'Напиши, что тебе нравится: два предмета или занятия. Не пропускай de.'},
numeros:{rule:'Сначала выучи 1–5: um, dois, três, quatro, cinco. Затем добавь 6–10: seis, sete, oito, nove, dez. Reais — название валюты во множественном числе.',words:[['um, dois, três','один, два, три'],['quatro, cinco','четыре, пять'],['seis, sete, oito','шесть, семь, восемь'],['nove, dez','девять, десять']],read:['Uma água custa três reais. Um café custa cinco reais. Ana compra um café.','Сколько стоит кофе?',['Пять реалов','Три реала','Восемь реалов'],0],spell:['c_nco','i','Cinco — пять.'],photo:['Há uma cachoeira na imagem.','На изображении есть водопад.','Cachoeira — водопад. Не нужно считать потоки: начни с одного видимого объекта.'],model:['Quanto custa o café? Custa cinco reais. Quero um café, por favor.','Сколько стоит кофе? Пять реалов. Хочу кофе, пожалуйста.'],write:'Составь короткую переписку о цене: вопрос, цена и заказ.'},
horas:{rule:'Вопрос Que horas são? означает «который час?». Для одного часа — É uma hora. Для двух и дальше — São duas horas. Встреча в два — às duas.',words:[['Que horas são?','Который час?'],['uma hora','один час'],['às duas','в два часа'],['de manhã','утром']],read:['A biblioteca abre às nove. Ana combina um encontro às dez.','Во сколько встреча Аны?',['В десять','В девять','В два'],0],spell:['h_ras','o','Horas — часы. H в начале слова обычно не произносится.'],photo:['Há uma praia na cidade.','В городе есть пляж.','Praia — пляж. Для плана: Vamos à praia às dez — пойдём на пляж в десять.'],model:['Vamos nos encontrar às dez? Sim, às dez, na biblioteca.','Встретимся в десять? Да, в десять, в библиотеке.'],write:'Договорись о встрече: предложи время и место, затем подтверди.'},
cafe:{rule:'Самая простая просьба — название + por favor. Более полная: Quero um café, por favor. После заказа удобно спросить Quanto custa? и поблагодарить.',words:[['um café','кофе'],['uma água','вода'],['por favor','пожалуйста, в просьбе'],['obrigado / obrigada','спасибо']],read:['Ana: Um café e uma água, por favor.\nAtendente: Claro!\nAna: Obrigada!','Что заказала Ана?',['Кофе и воду','Два кофе','Только воду'],0],spell:['caf_','é','Café — кофе, ударение на последнем слоге.'],photo:['Há um mercado perto da água.','Рядом с водой есть рынок.','На фотографии рынок Белена. Mercado — рынок; perto — рядом.'],model:['Bom dia! Quero um café e uma água, por favor. Quanto custa? Obrigada!','Доброе утро! Хочу кофе и воду, пожалуйста. Сколько стоит? Спасибо!'],write:'Сделай заказ из двух напитков, спроси цену и поблагодари.'},
compras:{rule:'Для цены — Quanto custa? Для оплаты — Posso pagar com cartão? Чтобы попросить другой размер: Tem um tamanho maior? Начни с цены и оплаты, затем добавляй уточнения.',words:[['quanto custa','сколько стоит'],['cartão','карта'],['dinheiro','наличные / деньги'],['tamanho','размер']],read:['A camiseta custa vinte reais. Ana pergunta: Posso pagar com cartão? O vendedor responde: Sim.','Как Ана хочет заплатить?',['Картой','Только наличными','Не хочет платить'],0],spell:['cart_o','ã','Cartão — карта. Ã обозначает носовое звучание.'],photo:['Há cadeiras dentro do prédio.','Внутри здания есть стулья.','На снимке интерьер театра. Cadeiras — стулья; dentro — внутри.'],model:['Quanto custa esta camiseta? Posso pagar com cartão? Obrigada!','Сколько стоит эта футболка? Можно заплатить картой? Спасибо!'],write:'Напиши продавцу: спроси цену товара и уточни способ оплаты.'},
onde:{rule:'Сначала вопрос Onde fica…? Затем ориентиры: perto — близко, longe — далеко, à direita — справа, à esquerda — слева. Не надо сразу понимать весь длинный маршрут.',words:[['onde fica','где находится'],['perto / longe','близко / далеко'],['à direita','справа / направо'],['à esquerda','слева / налево']],read:['A farmácia fica perto da escola. O mercado fica longe. Ana procura a farmácia.','Что находится рядом со школой?',['Аптека','Рынок','Кафе'],0],spell:['on_e','d','Onde — где.'],photo:['Há um rio e árvores.','Есть река и деревья.','На фотографии река в Амазонии. Rio — река; árvores — деревья.'],model:['Onde fica a farmácia? Fica perto da escola, à direita. Obrigada!','Где аптека? Рядом со школой, справа. Спасибо!'],write:'Составь вопрос о нужном месте и короткий ответ с ориентиром.'},
poder:{rule:'Posso — могу я. Pode — можете вы / может он или она. После них действие не меняем: posso entrar, pode repetir. Preciso de ajuda — мне нужна помощь.',words:[['posso','могу я'],['pode repetir','можете повторить'],['preciso de ajuda','нужна помощь'],['mais devagar','медленнее']],read:['Ana: Não entendi. Pode repetir mais devagar?\nPaulo: Claro!','Что просит Ана?',['Повторить медленнее','Говорить быстрее','Закончить встречу'],0],spell:['aj_da','u','Ajuda — помощь.'],photo:['Há montanhas e vegetação.','Есть горы и растительность.','Montanhas — горы; vegetação — растительность. Называй только видимое.'],model:['Desculpe, não entendi. Pode repetir mais devagar? Preciso de ajuda.','Извините, не понял. Можете повторить медленнее? Мне нужна помощь.'],write:'Сообщи, что не понял, и попроси подходящую помощь двумя просьбами.'},
saude:{rule:'Для боли часто используем estou com dor de…: estou com dor de cabeça. Для записи: Quero marcar uma consulta. В этом занятии тренируем язык, а не медицинскую оценку.',words:[['dor de cabeça','головная боль'],['consulta','приём / консультация'],['marcar','записать / назначить'],['hoje / amanhã','сегодня / завтра']],read:['Ana está com dor de cabeça. Ela quer marcar uma consulta para amanhã.','На какой день Ана хочет записаться?',['На завтра','На вчера','Через месяц'],0],spell:['d_r','o','Dor — боль.'],photo:['Há dunas e água.','Есть дюны и вода.','На фотографии Ленсойс-Мараньенсис. Dunas — дюны; água — вода.'],model:['Bom dia! Estou com dor de cabeça. Quero marcar uma consulta para amanhã.','Доброе утро! У меня болит голова. Хочу записаться на приём на завтра.'],write:'Напиши в регистратуру: приветствие, одна жалоба и желаемый день записи.'},
telefone:{rule:'В коротком сообщении важно три вещи: зачем пишу, что прошу и когда нужно. Pode me mandar…? — можете прислать мне…? Me здесь получатель: мне.',words:[['mensagem','сообщение'],['endereço','адрес'],['mandar','отправить'],['Pode repetir?','Можете повторить?']],read:['Oi, Paulo! Pode me mandar o endereço? Vamos nos encontrar amanhã às dez. Ana.','Что просит прислать Ана?',['Адрес','Деньги','Учебник'],0],spell:['mens_gem','a','Mensagem — сообщение.'],photo:['Há uma árvore inclinada.','Есть наклонённое дерево.','На снимке известное дерево Жерикоакоары. Árvore — дерево; inclinada — наклонённая.'],model:['Oi, Paulo! Pode me mandar o endereço? Até amanhã! Ana.','Привет, Паулу! Можешь прислать мне адрес? До завтра! Ана.'],write:'Напиши знакомому короткое сообщение с одной ясной просьбой и завершением.'},
amanha:{rule:'Ближайший план: eu vou + действие, nós vamos + действие. Действие оставляем в начальной форме: vou estudar, vamos trabalhar. Amanhã указывает на завтра.',words:[['vou estudar','буду учиться'],['vamos','мы пойдём / собираемся'],['amanhã','завтра'],['depois','потом']],read:['Amanhã Ana vai estudar de manhã. Depois ela vai tomar um café com Paulo.','Что Ана сделает сначала?',['Будет учиться','Пойдёт за покупками','Приготовит ужин'],0],spell:['amanh_','ã','Amanhã — завтра. Последняя буква ã.'],photo:['Há montanhas na paisagem.','В пейзаже есть горы.','Montanhas — горы. Добавь план: Amanhã vou caminhar — завтра пойду гулять.'],model:['Amanhã vou estudar de manhã. Depois vou tomar um café com um amigo.','Завтра буду учиться утром. Потом выпью кофе с другом.'],write:'Расскажи о двух планах на завтра и свяжи их словом depois.'},
ontem:{rule:'Для рассказа о вчерашнем дне начни с ontem. Fui ao mercado — сходил на рынок. Fiquei em casa — остался дома. Сначала выбирай из этих готовых фраз.',words:[['ontem','вчера'],['fui','сходил / поехал'],['fiquei em casa','остался дома'],['depois','потом']],read:['Ontem Ana foi ao mercado. Depois ficou em casa e estudou português.','Куда Ана сходила?',['На рынок','В школу','В больницу'],0],spell:['ont_m','e','Ontem — вчера.'],photo:['Há água e árvores na imagem.','На изображении есть вода и деревья.','Для воспоминания: Ontem fui a um lugar assim — вчера побывал в похожем месте.'],model:['Ontem fui ao mercado. Depois fiquei em casa. Estudei português.','Вчера сходил на рынок. Потом остался дома. Учил португальский.'],write:'Напиши три события вчерашнего дня. Можно использовать предложенные готовые формы.'},
passado:{rule:'У многих глаголов на -ar форма eu в законченном прошлом оканчивается на -ei: comprei, trabalhei, estudei. Сначала научись связывать эти действия в рассказ, а не учить всю таблицу.',words:[['comprei','купил / купила'],['trabalhei','работал / работала'],['estudei','учился / училась'],['pão','хлеб']],read:['Ontem trabalhei de manhã. Comprei pão e café. À noite estudei português.','Что купил автор?',['Хлеб и кофе','Одежду','Книгу и ручку'],0],spell:['compr_i','e','Eu comprei — я купил.'],photo:['Há mar e rochas.','Есть море и скалы.','На фото Фернанду-ди-Норонья. Mar — море; rochas — скалы.'],model:['Ontem trabalhei de manhã. Depois comprei pão. À noite estudei português.','Вчера работал утром. Потом купил хлеб. Вечером учил португальский.'],write:'Напиши мини-историю из трёх законченных действий: утром, потом и вечером.'},
imperfeito:{rule:'Era и morava помогают описать прежнюю жизнь: eu era criança, eu morava aqui. Fui и comprei сообщают отдельные завершённые события. Достаточно различить фон и событие.',words:[['era','был / была; фон'],['morava','жил / жила раньше'],['quando','когда'],['criança','ребёнок']],read:['Quando eu era criança, morava perto da praia. Ontem fui à praia com minha irmã.','О чём первая фраза?',['О жизни в детстве','О завтрашнем плане','О цене билета'],0],spell:['crian_a','ç','Criança — ребёнок. Перед a здесь ç.'],photo:['Há uma praia e árvores.','Есть пляж и деревья.','Для фона: Eu morava perto da praia — раньше я жил рядом с пляжем.'],model:['Quando eu era criança, morava perto da praia. Ontem fui à praia com minha irmã.','В детстве я жил рядом с пляжем. Вчера сходил на пляж с сестрой.'],write:'Соедини одну фразу о прежней жизни и одно событие, которое произошло вчера.'},
comparar:{rule:'Больше признака: mais + слово + que. Меньше: menos + слово + que. Mais barato — дешевле, mais caro — дороже. Сравнивай конкретные два варианта.',words:[['mais barato','дешевле'],['mais caro','дороже'],['menos','меньше / менее'],['que / do que','чем, в сравнении']],read:['O ônibus é mais barato que o táxi. O táxi é mais rápido. Ana quer economizar e escolhe o ônibus.','Почему Ана выбирает автобус?',['Он дешевле','Он всегда быстрее','Он бесплатный'],0],spell:['bar_to','a','Barato — дешёвый.'],photo:['Há prédios iluminados à noite.','Ночью видны освещённые здания.','На фотографии вечерний Грамаду. À noite — ночью / вечером; iluminados — освещённые.'],model:['O ônibus é mais barato que o táxi. O táxi é mais rápido, mas prefiro economizar.','Автобус дешевле такси. Такси быстрее, но я предпочитаю сэкономить.'],write:'Сравни два варианта и объясни свой выбор одной причиной.'},
condicional:{rule:'Для мягкой просьбы используй готовую форму Poderia…? — могли бы…? Для желания — Gostaria de… — хотел бы… Здесь не требуется знать все условные формы.',words:[['poderia','могли бы'],['gostaria de','хотел бы'],['repetir','повторить'],['por favor','пожалуйста']],read:['Ana: Você poderia repetir o endereço, por favor?\nPaulo: Claro!','Зачем Ана использует poderia?',['Чтобы попросить мягче','Чтобы рассказать о вчерашнем дне','Чтобы попрощаться'],0],spell:['poder_a','i','Poderia — мог бы / могли бы.'],photo:['Há um prédio perto da água.','Рядом с водой есть здание.','На снимке дворец Кинтандинья. Для просьбы о месте: Poderia me dizer onde fica?'],model:['Bom dia! Você poderia repetir o endereço, por favor? Gostaria de anotar. Obrigada!','Доброе утро! Вы могли бы повторить адрес? Хотела бы записать. Спасибо!'],write:'Напиши вежливую просьбу и коротко объясни, зачем тебе это нужно.'},
conectores:{rule:'Porque даёт причину: estudo porque preciso. Mas показывает противопоставление: quero sair, mas chove. Por isso показывает результат: chove, por isso fico em casa.',words:[['porque','потому что'],['mas','но'],['por isso','поэтому'],['também','тоже / также']],read:['Quero ir à praia, mas está chovendo. Por isso vou ficar em casa e estudar.','Почему автор останется дома?',['Идёт дождь','Нужно купить хлеб','Пляж далеко'],0],spell:['porq_e','u','Porque — потому что.'],photo:['Há uma praia e palmeiras.','Есть пляж и пальмы.','Для причины можно написать: Gosto da praia porque é bonita — нравится пляж, потому что красивый.'],model:['Quero sair, mas está chovendo. Por isso vou ficar em casa. Vou estudar porque preciso praticar.','Хочу выйти, но идёт дождь. Поэтому останусь дома. Буду учиться, потому что нужно практиковаться.'],write:'Соедини три мысли: желание, препятствие и новый план. Используй mas и por isso.'},
opiniao:{rule:'Понятное мнение состоит из позиции и причины: Eu acho que… porque… После причины можно привести один пример. Não acho que… пока не требуется: начни с утвердительной фразы.',words:[['eu acho que','я считаю, что'],['importante','важный'],['por exemplo','например'],['na minha opinião','по моему мнению']],read:['Acho que a biblioteca é importante porque ajuda os moradores. Por exemplo, oferece livros e encontros de leitura.','Какую причину приводит автор?',['Библиотека помогает жителям','Все книги дорогие','Библиотека закрыта'],0],spell:['opini_o','ã','Opinião — мнение.'],photo:['Há casas e uma rua na cidade.','В городе есть дома и улица.','Для мнения: Acho esta cidade bonita — считаю этот город красивым.'],model:['Acho que a biblioteca é importante porque ajuda os moradores. Por exemplo, oferece livros.','Считаю библиотеку важной, потому что она помогает жителям. Например, предоставляет книги.'],write:'Вырази мнение о месте или услуге в городе: позиция, причина и один пример.'},
subjuntivo:{rule:'Не учим сложную таблицу. Запомним один бытовой кусочек: quando eu tiver tempo — когда у меня будет время. После него добавим знакомый план: vou estudar.',words:[['quando eu tiver tempo','когда у меня будет время'],['se eu tiver tempo','если у меня будет время'],['vou estudar','буду учиться'],['amanhã','завтра']],read:['Amanhã vou trabalhar. Se eu tiver tempo, vou estudar português. Depois vou descansar.','От чего зависит учёба?',['От наличия времени','От цены книги','От погоды'],0],spell:['tiv_r','e','Tiver в готовой фразе se eu tiver tempo.'],photo:['Há mar, montanhas e vegetação.','Есть море, горы и растительность.','Для плана: Se eu tiver tempo, vou visitar este lugar — если будет время, посещу это место.'],model:['Amanhã vou trabalhar. Se eu tiver tempo, vou estudar português. Depois vou descansar.','Завтра буду работать. Если будет время, поучу португальский. Потом отдохну.'],write:'Напиши основной план и дополнительный план, если останется время.'},
email:{rule:'Перед письмом реши: кому пишу и чего хочу. Затем три части: приветствие, ясная просьба с нужной датой, благодарность. В деловом письме избегаем слишком дружеского Oi, amigo!',words:[['Bom dia','добрый день / доброе утро, приветствие'],['gostaria de','хотел бы'],['remarcar','перенести на другое время'],['atenciosamente','с уважением']],read:['Bom dia! Gostaria de remarcar minha aula para sexta-feira. Poderia confirmar o horário? Obrigada. Ana.','Чего хочет Ана?',['Перенести занятие','Купить учебник','Отменить все занятия навсегда'],0],spell:['atencios_mente','a','Atenciosamente — с уважением.'],photo:['Há uma praia e o mar.','Есть пляж и море.','Для подписи: Esta foto mostra uma praia — это фото показывает пляж.'],model:['Bom dia! Gostaria de remarcar minha aula para sexta-feira. Poderia confirmar o horário? Obrigada. Atenciosamente, Ana.','Добрый день! Хотела бы перенести занятие на пятницу. Могли бы подтвердить время? Спасибо. С уважением, Ана.'],write:'Напиши письмо преподавателю: попроси перенести занятие, укажи день и попроси подтверждение.'},
resumo:{rule:'Сначала найди в объявлении: что изменилось, когда и что делать читателю. Затем передай именно эти сведения другу. Не добавляй причины, которых в исходнике нет.',words:[['aviso','объявление'],['fechado / fechada','закрыт / закрыта'],['amanhã','завтра'],['volta','возобновляется / возвращается']],read:['Aviso: a biblioteca está fechada hoje. O atendimento volta amanhã às nove. A devolução de livros pode ser feita amanhã.','Когда снова откроется обслуживание?',['Завтра в девять','Сегодня в девять','Через неделю'],0],spell:['av_so','i','Aviso — объявление.'],photo:['Há uma estrada entre montanhas.','Между горами есть дорога.','Estrada — дорога. Описывай то, что видно; не выдумывай, закрыта ли дорога.'],model:['A biblioteca está fechada hoje. Abre amanhã às nove. Podemos devolver os livros amanhã.','Библиотека сегодня закрыта. Откроется завтра в девять. Мы можем вернуть книги завтра.'],write:'Объясни другу объявление своими словами: что закрыто, когда откроется и когда вернуть книги.'},
conversa:{rule:'Когда не понял, не нужно угадывать. Сначала Não entendi. Затем конкретная просьба Pode repetir mais devagar? Наконец проверь смысл: Então, amanhã às dez? — значит, завтра в десять?',words:[['não entendi','не понял / не поняла'],['pode repetir','можете повторить'],['mais devagar','медленнее'],['então','значит / тогда']],read:['Paulo: Vamos amanhã às dez?\nAna: Não entendi. Pode repetir?\nPaulo: Amanhã às dez.\nAna: Certo! Até amanhã!','О чём договорились?',['О встрече завтра в десять','О покупке кофе сегодня','О встрече вчера'],0],spell:['repet_r','i','Repetir — повторить.'],photo:['Há um prédio e água na paisagem.','В пейзаже есть здание и вода.','На фотографии музей в Нитерое. Опиши форму и окружение, не угадывая мнение людей.'],model:['Não entendi. Pode repetir mais devagar? Então, amanhã às dez? Certo! Até amanhã!','Не понял. Можете повторить медленнее? Значит, завтра в десять? Хорошо! До завтра!'],write:'Составь переписку: попроси повторить, уточни время и подтверди встречу.'}
};
for(const u of Object.values(units)){u.checks=['Я выполнил просьбу задания','Смысл понятен без дополнительных объяснений','Я сравнил свой текст с образцом'];}
for(const l of window.BoraCourses[0].lessons)units[l.id].photo=[l.examples[0][0],l.examples[0][1],l.scene];
window.BoraLessonContent=units;
})();
